-- Balletmate discovery coverage expansion for dense neighborhoods.
-- Run in Supabase SQL editor after studio_discovery.sql and Seoul upgrade.
on conflict(id) do update set region_name=excluded.region_name,latitude=excluded.latitude,longitude=excluded.longitude,radius_m=excluded.radius_m;
update public.studio_discovery_cursor set next_region_id=66,updated_at=now() where id=1;
